import{_ as n}from"./chunks/calendar-plus.DIshg-3Q.js";import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Calendar +","description":"Eigenes Kalender-Widgetset mit automatischer Kalendererkennung, Terminliste und Detail-Popup.","frontmatter":{"title":"Calendar +","description":"Eigenes Kalender-Widgetset mit automatischer Kalendererkennung, Terminliste und Detail-Popup."},"headers":[],"relativePath":"projects/grafik-visual-studio/calendar-plus.md","filePath":"projects/grafik-visual-studio/calendar-plus.md","lastUpdated":1793113714000}'),s={name:"projects/grafik-visual-studio/calendar-plus.md"};function l(d,e,o,g,u,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="calendar" tabindex="-1">Calendar + <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar +&quot;">​</a></h1><p><strong>Calendar + 0.1.1</strong> ist ein eigenes externes Widgetset von <strong>rockbaer2007</strong> für <strong>Grafik Visual Studio 0.1.267 oder neuer</strong>. Es erkennt alle verfügbaren Home-Assistant-Kalender automatisch und zeigt kommende Termine als kompakte Karte oder ausgeklappte Liste. Alle Kalender sind zunächst aktiviert.</p><p>Die Runtime mit Beispieldaten:</p><p><img src="'+n+'" alt="Calendar + mit farbigen Kalenderkacheln, Tagesgruppen und Terminliste"></p><h2 id="originalprojekt" tabindex="-1">Originalprojekt <a class="header-anchor" href="#originalprojekt" aria-label="Permalink to &quot;Originalprojekt&quot;">​</a></h2><p>Vorbild ist <strong><a href="https://github.com/xBourner/calendar-card-plus" target="_blank" rel="noreferrer">calendar-card-plus von xBourner</a></strong>, veröffentlicht unter der <a href="https://github.com/xBourner/calendar-card-plus/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT-Lizenz</a>, Copyright (c) 2026 xBourner. Calendar + verwendet eine eigene Studio-Implementierung und ein eigenes Palettensymbol. Originalcode und Originalgrafiken sind nicht eingebunden. Das Set ist unabhängig von Industrial und der separat nutzbaren Lovelace-Originalkarte.</p><h2 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h2><ol><li>Studio auf <strong>0.1.267 oder neuer</strong> aktualisieren.</li><li><a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/calendar-plus/ugso.calendar-plus.wg" target="_blank" rel="noreferrer">ugso.calendar-plus.wg herunterladen</a>.</li><li>Unter <strong>Einstellungen → Widget-Pakete → Lokal</strong> installieren.</li><li><strong>Calendar + → Kalender +</strong> aus der Palette auf die Seite ziehen.</li></ol><p>Das Paket enthält deklarative Daten, ein Symbol, Anleitung und MIT-Lizenz. Der feste Host-Renderer <code>calendar-plus</code> wird von Studio bereitgestellt; keine ausführbaren Paketskripte. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/calendar-plus" target="_blank" rel="noreferrer">Quellcode und Paket-Anleitung</a>.</p><h2 id="meine-kalender" tabindex="-1">Meine Kalender <a class="header-anchor" href="#meine-kalender" aria-label="Permalink to &quot;Meine Kalender&quot;">​</a></h2><p>Alle verfügbaren <code>calendar.*</code>-Entitäten werden erkannt, einschließlich Kalendern ohne Registry-Eintrag. In Home Assistant deaktivierte Registry-Einträge werden ausgelassen. Unter <strong>Meine Kalender</strong> erscheint für jeden Kalender ein eigener Bereich mit Entitäts-ID, einer <strong>Checkbox rechts oben zum Anzeigen/Ausblenden</strong>, <strong>Farbe</strong> und optionaler <strong>Hintergrundfarbe</strong>. Es gibt keine manuell einzutragende Kalenderanzahl.</p><p>Ab Studio <strong>0.1.268</strong> heißt die Gruppe <strong>Kacheleinstellungen</strong> (zuvor „Farben“). <strong>Kalenderkachelgröße</strong> bietet vier feste Größen: <strong>Sehr klein 36 × 44 px</strong>, <strong>Klein 44 × 52 px</strong>, <strong>Mittel 58 × 64 px</strong> (Standard) und <strong>Groß 76 × 82 px</strong>. Die Auswahl gilt für Terminliste und Detail-Popup. Kopftext mindestens <strong>12 px</strong>, Tagesziffer mindestens <strong>24 px</strong>, unabhängig von der allgemeinen Schriftgröße. Auch schmale Widgets behalten die gewählte Größe. Vorhandene Pakete 0.1.0/0.1.1 erhalten die Einstellungen mit dem Studio-Update; eine Neuinstallation ist nicht nötig. Der Kalender benötigt keine Datenfluss-Einstellungen oder Ein-/Ausgangspunkte.</p><p>Die Auswahl und Farben bleiben anhand der Entitäts-ID gespeichert. Neu hinzugekommene Kalender sind automatisch eingeblendet; ausgeblendete Kalender werden nicht nach Terminen abgefragt. Die Anzahl erkannter Kalender ist nicht begrenzt. Abfragen erfolgen in Gruppen von höchstens 20 Kalendern über die Home-Assistant-Schnittstelle.</p><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Ab Studio <strong>0.1.270</strong> lässt sich unter <strong>Kacheleinstellungen → Kachel-Eckenradius (px)</strong> ein gemeinsamer Radius für alle vier Ecken der Datumskachel einstellen: <strong>0 = eckig</strong>, Vorgabe <strong>10 px</strong>, maximal <strong>100 px</strong>. Gilt auch im Detail-Popup.</p><p>Kalender und Drucker bieten unter <strong>Eigenschaften → WIDGET</strong> jetzt alle CSS-Bereiche: <strong>CSS Allgemein</strong>, <strong>CSS Font &amp; Text</strong>, <strong>CSS Hintergrund</strong>, <strong>CSS Ränder</strong> und <strong>CSS Schatten und Abstand</strong>. Die vier zusätzlichen Gruppen sind zunächst ausgeschaltet, um die bisherige Darstellung zu erhalten. Den Haken der jeweiligen Gruppe einschalten, dann Schrift, Hintergrund/Bild, Rahmen, Radius, Schatten und Abstände einstellen. Diese Werte gestalten die sichtbare Kartenfläche; der äußere Radius unter <strong>CSS Ränder</strong> ist unabhängig vom Radius der kleinen Datumskacheln. Fachfarben wie Kalenderfarben und Druckerstatus bleiben eigene Einstellungen. <strong>CSS Allgemein</strong> bleibt für Position, Größe und Sichtbarkeit aktiv. Kein neues Paket nötig.</p><p>Ab Studio <strong>0.1.269</strong> bieten die <strong>Kacheleinstellungen</strong> zusätzlich <strong>Schriftgröße oben</strong> (Monat/Wochentag, bis 72 px) und <strong>Schriftgröße unten</strong> (Tageszahl, bis 120 px). <strong>0 = automatisch</strong> verwendet die Vorgaben der gewählten Kachelgröße. Eigene Werte dürfen kleiner sein und werden bei Platzmangel automatisch begrenzt. Die gespeicherten Wunschwerte bleiben erhalten, sodass größere Kacheln wieder größere Schrift nutzen können.</p><p>Der farbige Kopfbereich wächst mit der oberen Schrift und etwas Innenabstand, bleibt jedoch auf <strong>höchstens ein Drittel der Kachelhöhe</strong> begrenzt. Die Tageszahl wird in den restlichen Bereich eingepasst. Die Kachelgröße bleibt unverändert. Diese Einstellungen gelten für Terminliste und Detail-Popup und benötigen kein neues Widget-Paket.</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Einstellung</th></tr></thead><tbody><tr><td>Konfiguration</td><td>Bezeichnung, Vorschau <strong>1–90 Tage</strong>, <strong>1–20</strong> sichtbare Termine, Ereignisse ausklappen, Detail-Popup, Trenner.</td></tr><tr><td>Gruppierung</td><td>Nach Tag, zusätzlich nach Kalender; optional leere Tage anzeigen.</td></tr><tr><td>Bevorstehende Ereignisse</td><td>Relative Zeit wie „Morgen“, „In 2 Tagen“ oder „Läuft“ ein-/ausblenden.</td></tr><tr><td>Text &amp; Sichtbarkeit</td><td>Kalendername, Datum, Ort, Dauer, Uhrzeit und Wochentag einzeln schaltbar; Wochentag ausgeschrieben oder kurz, Monat/Wochentag in der Datumskachel tauschen.</td></tr><tr><td>Kacheleinstellungen</td><td>Vier Kachelgrößen, Browser-Theme automatisch oder fest Hell/Dunkel, Akzentfarbe und Schriftgröße <strong>10–24 px</strong>. Kalenderfarben und Hintergründe separat je Kalender.</td></tr><tr><td>Größe</td><td>Vorgabe <strong>480 × 460 px</strong>, mindestens <strong>260 × 180 px</strong>; bei wenig Platz scrollt die Terminliste.</td></tr></tbody></table><p>Ohne ausgeklappte Liste bleibt ein Termin sichtbar. In der Runtime öffnet ein Klick auf einen Termin oder <strong>Alle Termine</strong> das Detail-Popup mit bis zu 100 Terminen. Dort erscheinen vollständiges Datum, Ort und Beschreibung, sofern vorhanden. Texte werden als Klartext dargestellt. <strong>Schließen</strong>, Escape oder ein Klick außerhalb schließen das Popup.</p><h2 id="daten-und-aktualisierung" tabindex="-1">Daten und Aktualisierung <a class="header-anchor" href="#daten-und-aktualisierung" aria-label="Permalink to &quot;Daten und Aktualisierung&quot;">​</a></h2><p>Editor und Runtime lesen Termine über <code>calendar.get_events</code>. Ganztagstermine berücksichtigen das exklusive Enddatum; abgelaufene Termine werden entfernt. Unter <strong>Konfiguration → Automatisch aktualisieren (60 s)</strong> lässt sich die regelmäßige Aktualisierung abschalten (Vorgabe: an). Beim Runtime-Seitenaufruf werden Kalender und Termine frisch geladen, auch bei deaktivierter Automatik. <strong>↻</strong> aktualisiert weiterhin manuell. Die Kalendererkennung wird dabei ebenfalls erneuert.</p><p>Aktualisierungen ersetzen nur die Terminlisten und erhalten Scrollpositionen sowie ein geöffnetes Detail-Popup. Zustandsänderungen anderer Live-Widgets bauen den unveränderten Kalender nicht neu auf. Beim Verlassen der Seite endet dessen Aktualisierung.</p><p>„Keine Kalender gefunden“, „Alle Kalender ausgeblendet“, „Keine kommenden Termine“ und ein Ladefehler sind unterschiedliche Zustände. Ein Fehler wird nicht als leerer Kalender ausgegeben. Die Sprache folgt automatisch der Studio-Einstellung <strong>DE/EN</strong>; eigene Bezeichnungen und Termininhalte bleiben unverändert.</p><h2 id="umfang-dieser-version" tabindex="-1">Umfang dieser Version <a class="header-anchor" href="#umfang-dieser-version" aria-label="Permalink to &quot;Umfang dieser Version&quot;">​</a></h2><p>Diese Version liest Termine. <strong>Neuer Termin</strong>, Bearbeiten und Löschen sind noch nicht enthalten. Kalender müssen in Home Assistant verfügbar sein; es gibt keine direkte ICS-/Google-Anmeldung. Die Originalkarte muss nicht zusätzlich in HACS installiert werden.</p>',26)])])}const m=t(s,[["render",l]]);export{b as __pageData,m as default};
